#!/usr/bin/env python3
"""Pachpedi Naka | Ultra Visual Studio  (version 2: adaptive-control upgrade)

Single-file application. The embedded engine archive contains the original research engine PLUS the upgrade:
  * src/adaptive_controllers.py  competitor-style score controller (faithful port) and the final adaptive-pressure controller
  * src/webster.py               Webster-optimised fixed-time baseline
  * src/scenarios.py             standard demand levels and stress scenarios
  * src/metrics_extended.py      all-vehicle waits, fairness, switches, phase time, tail waits
  * src/benchmark.py             paired five-controller benchmark with exports, charts and a data-driven report
The original two-controller pipeline (src/final_pipeline.py) and the classic demo window are kept.

Launch:             py Pachpedi_Naka_Ultra_Visual_Studio.py
Headless checks:    py Pachpedi_Naka_Ultra_Visual_Studio.py --selftest
Original window:    py Pachpedi_Naka_Ultra_Visual_Studio.py --classic
PROVISIONAL SYNTHETIC DEMO DATA - NOT CALIBRATED OR VALIDATED FOR REAL-WORLD USE.
"""

from __future__ import annotations
import base64, csv, json, os, random, shutil, subprocess, sys, threading, time, zipfile
from pathlib import Path
import tkinter as tk
from tkinter import ttk, messagebox, filedialog
from tkinter.scrolledtext import ScrolledText
import dataclasses, shutil
import argparse, bisect, datetime, hashlib, importlib, importlib.util, math, tempfile, traceback
import tkinter.font as tkfont

APP_TITLE = "Pachpedi Naka | Smart Traffic Lab"
HERE = Path(__file__).resolve().parent
ENGINE_DIR = HERE / "Pachpedi_Naka_Engine_v2"   # v2: engine extended with the benchmark and adaptive controllers
PROJECT_DIR = ENGINE_DIR / "Pachpedi_Naka_Final_Working_Package" / "pachpedi_traffic"
ENGINE_ZIP_B64 = ""


def ensure_engine():
    marker = PROJECT_DIR / "src" / "benchmark.py"
    if marker.exists():
        return PROJECT_DIR
    ENGINE_DIR.mkdir(parents=True, exist_ok=True)
    archive = ENGINE_DIR / "embedded_project.zip"
    archive.write_bytes(base64.b64decode(ENGINE_ZIP_B64))
    with zipfile.ZipFile(archive, "r") as zf:
        # Prevent path traversal if the embedded archive is ever replaced.
        root = ENGINE_DIR.resolve()
        for info in zf.infolist():
            target = (ENGINE_DIR / info.filename).resolve()
            if target != root and root not in target.parents:
                raise RuntimeError("Unsafe path found in embedded project archive")
        zf.extractall(ENGINE_DIR)
    archive.unlink(missing_ok=True)
    if not marker.exists():
        raise RuntimeError("Could not extract the embedded research engine")
    return PROJECT_DIR


class TrafficDemo:
    """Animated, explicitly illustrative intersection demo (not a live signal)."""
    ROADS = {"N": (496, 62), "S": (184, 448), "E": (592, 366), "W": (88, 144)}   # beside each approach, off the lanes
    COLORS = {"N": "#38bdf8", "S": "#f59e0b", "E": "#a78bfa", "W": "#34d399"}
    LABELS = {"N": "NORTH", "S": "SOUTH", "E": "EAST", "W": "WEST"}

    def __init__(self, canvas, status_cb, stats_cb):
        self.canvas, self.status_cb, self.stats_cb = canvas, status_cb, stats_cb
        self.running = False
        self.mode = "queue_responsive"
        self.demand = "Medium"
        self.t = 0
        self.queues = {k: 5 for k in "NSEW"}
        self.passed = 0
        self.movers = []
        self.after_id = None
        self._last_spawn = {k: -20 for k in "NSEW"}
        self._pulse = 0
        self.draw_scene()
        self.render_cars()

    def draw_scene(self):
        c = self.canvas
        c.delete("all")
        c.configure(background="#07111f")
        c.create_rectangle(0, 0, 680, 510, fill="#07111f", outline="")
        # Subtle city blocks, deliberately low-contrast behind the junction.
        blocks = [(20, 25, 210, 145), (460, 25, 650, 145),
                  (20, 365, 210, 485), (460, 365, 650, 485)]
        for x1, y1, x2, y2 in blocks:
            c.create_rectangle(x1, y1, x2, y2, fill="#0b1b2c", outline="#132a3e", width=2)
            for wx in range(x1 + 14, x2 - 10, 28):
                for wy in range(y1 + 14, y2 - 10, 26):
                    c.create_rectangle(wx, wy, wx + 10, wy + 8, fill="#10263a", outline="")
        # Road deck and shoulders
        c.create_rectangle(248, 0, 432, 510, fill="#202d3b", outline="#344457", width=2)
        c.create_rectangle(0, 163, 680, 347, fill="#202d3b", outline="#344457", width=2)
        c.create_rectangle(260, 0, 420, 510, fill="#263443", outline="")
        c.create_rectangle(0, 175, 680, 335, fill="#263443", outline="")
        # Lane markings for LEFT-HAND traffic (as in India): solid double-yellow median, dashed white
        # lane dividers; nothing is painted inside the junction box or across the crosswalks.
        for y in range(0, 510, 34):
            if y + 16 < 146 or y > 364:
                for x in (298, 382):
                    c.create_line(x, y, x, y+16, fill="#718096", width=2)
        for x in range(0, 680, 34):
            if x + 16 < 222 or x > 458:
                for y in (213, 297):
                    c.create_line(x, y, x+16, y, fill="#718096", width=2)
        for x in (336, 344):
            c.create_line(x, 0, x, 146, fill="#d4a72c", width=2)
            c.create_line(x, 364, x, 510, fill="#d4a72c", width=2)
        for y in (251, 259):
            c.create_line(0, y, 222, y, fill="#d4a72c", width=2)
            c.create_line(458, y, 680, y, fill="#d4a72c", width=2)
        # Stop lines cover only the INBOUND carriageway of each approach; the crosswalk lies between the
        # stop line and the junction box.
        c.create_line(344, 146, 420, 146, fill="#e2e8f0", width=3)   # North approach (southbound)
        c.create_line(260, 364, 336, 364, fill="#e2e8f0", width=3)   # South approach (northbound)
        c.create_line(222, 175, 222, 251, fill="#e2e8f0", width=3)   # West approach (eastbound)
        c.create_line(458, 259, 458, 335, fill="#e2e8f0", width=3)   # East approach (westbound)
        for x in range(270, 414, 18):
            c.create_rectangle(x, 152, x+9, 170, fill="#cbd5e1", outline="")
            c.create_rectangle(x, 340, x+9, 358, fill="#cbd5e1", outline="")
        for y in range(185, 326, 18):
            c.create_rectangle(230, y, 248, y+9, fill="#cbd5e1", outline="")
            c.create_rectangle(432, y, 450, y+9, fill="#cbd5e1", outline="")
        # The junction box is kept clear so straight-through traffic is not blocked (the old centre island
        # was removed). The pulse ring is kept but hidden so the animation code is unchanged.
        self.pulse_id = c.create_oval(286, 201, 394, 309, outline="#1d5266", width=2, state="hidden")
        c.create_text(340, 247, text="PACHPEDI", fill="#3b556e", font=("Segoe UI", 10, "bold"))
        c.create_text(340, 263, text="NAKA", fill="#3b556e", font=("Segoe UI", 10, "bold"))
        # Direction badges
        for d, (x, y) in self.ROADS.items():
            c.create_text(x, y, text=self.LABELS[d], fill="#e2e8f0", font=("Segoe UI", 9, "bold"))
        positions = {"N": (452, 118), "S": (228, 392), "E": (488, 372), "W": (192, 138)}   # on the kerb beside each stop line
        self.light_ids = {}
        self.light_halos = {}
        for d, (x, y) in positions.items():
            c.create_oval(x-20, y-25, x+20, y+25, fill="#0a1522", outline="#40546a", width=2)
            c.create_rectangle(x-12, y-18, x+12, y+18, fill="#0a1019", outline="#708196", width=1)
            self.light_halos[d] = c.create_oval(x-8, y-8, x+8, y+8, fill="#263746", outline="")
            self.light_ids[d] = c.create_oval(x-5, y-5, x+5, y+5, fill="#475569", outline="")
        c.create_text(12, 494, anchor="w",
                      text="ILLUSTRATIVE SIMULATION  •  SYNTHETIC ARRIVALS  •  NOT A LIVE ROAD FEED",
                      fill="#8da4ba", font=("Segoe UI", 7, "bold"))

    def current_green(self):
        if self.mode == "fixed_time":
            return "NSEW"[int(self.t // 10) % 4]
        maxq = max(self.queues.values())
        candidates = [d for d in "NSEW" if self.queues[d] == maxq]
        return candidates[(self.t // 8) % len(candidates)]

    def _draw_vehicle(self, x, y, direction, tag="car"):
        c = self.canvas
        color = self.COLORS[direction]
        if direction in ("N", "S"):
            x1, y1, x2, y2 = x-7, y-11, x+7, y+11
            c.create_rectangle(x1+2, y1+2, x2+2, y2+2, fill="#050b12", outline="", tags=tag)
            c.create_rectangle(x1, y1, x2, y2, fill=color, outline="#eaf4ff", width=1, tags=tag)
            c.create_rectangle(x1+2, y1+3, x2-2, y1+7, fill="#cdeeff", outline="", tags=tag)
            c.create_line(x1+2, y2-3, x2-2, y2-3, fill="#f8fafc", width=1, tags=tag)
        else:
            x1, y1, x2, y2 = x-11, y-7, x+11, y+7
            c.create_rectangle(x1+2, y1+2, x2+2, y2+2, fill="#050b12", outline="", tags=tag)
            c.create_rectangle(x1, y1, x2, y2, fill=color, outline="#eaf4ff", width=1, tags=tag)
            c.create_rectangle(x1+3, y1+2, x1+7, y2-2, fill="#cdeeff", outline="", tags=tag)
            c.create_line(x2-3, y1+2, x2-3, y2-2, fill="#f8fafc", width=1, tags=tag)

    def render_cars(self):
        c = self.canvas
        c.delete("car")
        # Queue vehicles sit behind the stop line.
        for d in "NSEW":
            q = min(12, self.queues[d])
            for i in range(q):
                row = i // 2
                if d == "N": x, y = (363, 401)[i % 2], 130 - row*24
                elif d == "S": x, y = (317, 279)[i % 2], 380 + row*24
                elif d == "W": x, y = 206 - row*24, (232, 194)[i % 2]
                else: x, y = 474 + row*24, (278, 316)[i % 2]
                self._draw_vehicle(x, y, d)
        # Moving vehicles travel through the junction on the active approach.
        for car in self.movers:
            p, d = car["p"], car["d"]
            if d == "N": x, y = 363, -20 + p*550
            elif d == "S": x, y = 317, 530 - p*550
            elif d == "W": x, y = -20 + p*720, 232
            else: x, y = 700 - p*720, 278
            self._draw_vehicle(x, y, d, "car")
        green = self.current_green()
        for d, item in self.light_ids.items():
            color = "#34d399" if d == green else "#ef4444"
            c.itemconfigure(item, fill=color)
            c.itemconfigure(self.light_halos[d], fill=color if d == green else "#4b2028")
        self._pulse = (self._pulse + 1) % 24
        r = 48 + (self._pulse % 12)
        c.coords(self.pulse_id, 340-r, 255-r, 340+r, 255+r)
        c.itemconfigure(self.pulse_id, outline="#164e63" if self._pulse < 12 else "#0e3549")
        self.status_cb(f"SIM TIME  {self.t:04d}s   •   GREEN: {self.LABELS[green]}   •   MODE: {self.mode.replace('_',' ').upper()}")
        self.stats_cb(self.passed, sum(self.queues.values()), self.queues.copy())

    def tick(self):
        if not self.running:
            return
        self.t += 1
        multiplier = {"Low": 0.45, "Medium": 0.8, "High": 1.25}[self.demand]
        for d in "NSEW":
            if random.random() < 0.24 * multiplier:
                self.queues[d] = min(60, self.queues[d] + 1)
        green = self.current_green()
        # Launch a vehicle only when that approach has a queue and is green.
        if self.queues[green] > 0 and self.t - self._last_spawn[green] >= 3:
            self.queues[green] -= 1
            self.movers.append({"d": green, "p": 0.0})
            self._last_spawn[green] = self.t
        for car in self.movers:
            car["p"] += 0.10
        arrived = sum(1 for car in self.movers if car["p"] >= 1.0)
        self.passed += arrived
        self.movers = [car for car in self.movers if car["p"] < 1.0]
        self.render_cars()
        self.after_id = self.canvas.after(90, self.tick)

    def start(self):
        if not self.running:
            self.running = True
            self.tick()

    def pause(self):
        self.running = False
        if self.after_id:
            try:
                self.canvas.after_cancel(self.after_id)
            except tk.TclError:
                pass
            self.after_id = None
        self.render_cars()

    def reset(self):
        self.pause()
        self.t, self.passed = 0, 0
        self.queues = {k: 5 for k in "NSEW"}
        self.movers = []
        self._last_spawn = {k: -20 for k in "NSEW"}
        self.draw_scene()
        self.render_cars()


