        self.title(APP_TITLE)
        self.geometry("1320x850")
        self.minsize(1120, 760)
        self.configure(bg="#07111f")
        self.style = ttk.Style(self)
        try: self.style.theme_use("clam")
        except tk.TclError: pass
        self.style.configure("TFrame", background="#07111f")
        self.style.configure("TLabel", background="#0b1220", foreground="#e2e8f0", font=("Segoe UI", 10))
        self.style.configure("Header.TLabel", font=("Segoe UI", 25, "bold"), foreground="#f8fafc")
        self.style.configure("Sub.TLabel", font=("Segoe UI", 9), foreground="#7dd3fc")
        self.style.configure("TButton", font=("Segoe UI", 9, "bold"), padding=9, background="#173449", foreground="#eaf6ff")
        self.mode = tk.StringVar(value="queue_responsive")
        self.demand = tk.StringVar(value="Medium")
        self.seed_count = tk.StringVar(value="10")
        self.bootstrap_count = tk.StringVar(value="10000")
        self.status = tk.StringVar(value="Ready. Start the illustration or run the research experiment.")
        self.stat_vars = {"passed":tk.StringVar(value="0"), "waiting":tk.StringVar(value="20"), "queues":tk.StringVar(value="N 5  •  S 5  •  E 5  •  W 5")}
        self.build_ui()
        self.demo = TrafficDemo(self.canvas, self.status.set, self.update_stats)
        self.demo.mode = self.mode.get()
        self.demo.demand = self.demand.get()
