        ttk.Label(top, text="PACHPEDI NAKA  /  SMART TRAFFIC LAB", style="Header.TLabel").pack(anchor="w")
        ttk.Label(top, text="ADAPTIVE SIGNAL SIMULATOR     •     LIVE VISUALISATION     •     REPRODUCIBLE RESEARCH", style="Sub.TLabel").pack(anchor="w", pady=(3,0))
        warning = tk.Label(self, text="RESEARCH DISCLAIMER  •  Synthetic assumptions only. Not calibrated or validated for real-world signal control.", bg="#422006", fg="#fde68a", font=("Segoe UI",9,"bold"), padx=12, pady=7, anchor="w")
        warning.pack(fill="x", padx=18, pady=(7,12))
        main = ttk.Frame(self, padding=(18,0,18,8)); main.pack(fill="both", expand=True)
        left = ttk.Frame(main); left.pack(side="left", fill="both", expand=True)
        right = ttk.Frame(main, padding=(14,0,0,0), width=300); right.pack(side="right", fill="y")
        self.canvas = tk.Canvas(left, width=680, height=510, bg="#07111f", highlightthickness=1, highlightbackground="#256079", relief="flat")
        self.canvas.pack(fill="both", expand=True)
        controls = ttk.Frame(left, padding=(0,10,0,0)); controls.pack(fill="x")
        ttk.Button(controls, text="▶ Start", command=self.start_demo).pack(side="left", padx=(0,6))
        ttk.Button(controls, text="Ⅱ Pause", command=lambda:self.demo.pause()).pack(side="left", padx=6)
        ttk.Button(controls, text="↻ Reset", command=lambda:self.demo.reset()).pack(side="left", padx=6)
        ttk.Label(right, text="CONTROLLER", font=("Segoe UI",10,"bold")).pack(anchor="w", pady=(0,5))
        ttk.Radiobutton(right, text="Queue-responsive", variable=self.mode, value="queue_responsive", command=self.change_mode).pack(anchor="w", pady=2)
        ttk.Radiobutton(right, text="Fixed-time", variable=self.mode, value="fixed_time", command=self.change_mode).pack(anchor="w", pady=2)
