_PAIRED_ALIASES = {
    "n": ("n_pairs", "paired_n"),
    "fixed": ("fixed_mean_wait_seconds", "fixed_mean_wait_s"),
    "resp": ("queue_responsive_mean_wait_seconds", "responsive_mean_wait_s"),
    "diff": ("paired_difference_responsive_minus_fixed_seconds", "mean_paired_difference_responsive_minus_fixed_s"),
    "red": ("relative_wait_reduction_percent", "relative_reduction_percent"),
    "lo": ("bootstrap_95ci_difference_low_seconds", "bootstrap_95ci_low_s"),
    "hi": ("bootstrap_95ci_difference_high_seconds", "bootstrap_95ci_high_s"),
}


def _to_float(text):
    try:
        return float(text)
    except (TypeError, ValueError):
        return None


class ExperimentResults:
    def __init__(self, folder, summary, paired, metadata, figures):
        self.folder, self.summary, self.paired, self.metadata, self.figures = folder, summary, paired, metadata, figures

    def summary_value(self, demand, capacity, controller, field):
        for r in self.summary:
            if r.get("demand_level") == demand and r.get("capacity_level") == capacity and r.get("controller") == controller:
                return _to_float(r.get(field))
        return None


def load_results_folder(folder):
    """Read summary_by_scenario.csv / paired_comparisons.csv / experiment_metadata.json.
    Raises ValueError with a readable message when the folder is unusable."""
    folder = Path(folder)
    sfile, pfile = folder / "summary_by_scenario.csv", folder / "paired_comparisons.csv"
    if not sfile.is_file() or not pfile.is_file():
        raise ValueError(f"{folder} does not contain summary_by_scenario.csv and paired_comparisons.csv")
    with sfile.open(newline="", encoding="utf-8") as f:
        summary = [{k.strip(): v for k, v in row.items()} for row in csv.DictReader(f)]
    paired = []
    with pfile.open(newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            row = {k.strip(): v for k, v in row.items()}
            norm = {"demand": row.get("demand_level"), "capacity": row.get("capacity_level")}
            for key, names in _PAIRED_ALIASES.items():
                norm[key] = next((_to_float(row[n]) for n in names if n in row), None)
            paired.append(norm)
    if not summary or not paired:
        raise ValueError(f"{folder}: result tables are empty")
    metadata = {}
    mfile = folder / "experiment_metadata.json"
    if mfile.is_file():
        try:
            metadata = json.loads(mfile.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            metadata = {}
    figs = sorted((folder / "figures").glob("*.png")) if (folder / "figures").is_dir() else []
    return ExperimentResults(folder, summary, paired, metadata, figs)


class BenchmarkResults:
    """Output of ``python -m src.benchmark`` (five controllers, scenario suite)."""

    def __init__(self, folder, summary, paired, metadata, figures):
        self.folder, self.summary, self.paired, self.metadata, self.figures = folder, summary, paired, metadata, figures

    def value(self, scenario, controller, field, capacity="baseline_capacity"):
        for r in self.summary:
            if r["scenario"] == scenario and r["controller"] == controller and r["capacity_level"] == capacity:
                return _to_float(r.get(field))
        return None

    def pair(self, scenario, controller, baseline="fixed_time", capacity="baseline_capacity", definition="all_vehicle"):
        for r in self.paired:
            if (r["scenario"], r["controller"], r["baseline"], r["capacity_level"], r["wait_definition"]) == (scenario, controller, baseline, capacity, definition):
                return {k: (_to_float(v) if k not in ("scenario", "controller", "baseline", "capacity_level", "wait_definition") else v) for k, v in r.items()}
        return None


def load_benchmark_folder(folder):
    folder = Path(folder)
    sfile, pfile = folder / "summary_by_scenario_controller.csv", folder / "paired_comparisons.csv"
    if not sfile.is_file() or not pfile.is_file():
        raise ValueError(f"{folder} does not contain summary_by_scenario_controller.csv and paired_comparisons.csv")
    with sfile.open(newline="", encoding="utf-8") as f:
        summary = [{k.strip(): v for k, v in row.items()} for row in csv.DictReader(f)]
    with pfile.open(newline="", encoding="utf-8") as f:
        paired = [{k.strip(): v for k, v in row.items()} for row in csv.DictReader(f)]
    if not summary or not paired:
        raise ValueError(f"{folder}: result tables are empty")
    metadata = {}
    if (folder / "experiment_metadata.json").is_file():
        try:
            metadata = json.loads((folder / "experiment_metadata.json").read_text(encoding="utf-8"))
        except (OSError, ValueError):
            metadata = {}
    figs = sorted((folder / "figures").glob("*.png")) if (folder / "figures").is_dir() else []
    return BenchmarkResults(folder, summary, paired, metadata, figs)


def load_any_results(folder):
    """Benchmark folder (new format) or legacy two-controller folder (original pipeline)."""
    folder = Path(folder)
    if (folder / "summary_by_scenario_controller.csv").is_file():
        return load_benchmark_folder(folder)
    return load_results_folder(folder)


def find_result_sources(project):
    """[(label, folder)] of result folders that currently exist (new benchmark first, legacy last)."""
    out = []
    if (BENCH_DIR / "summary_by_scenario_controller.csv").is_file():
        out.append(("Latest benchmark run", BENCH_DIR))
    if project is not None:
        emb = Path(project) / "outputs" / "benchmark"
        if (emb / "summary_by_scenario_controller.csv").is_file():
            out.append(("Embedded benchmark (20 seeds)", emb))
    if (RESULTS_DIR / "summary_by_scenario.csv").is_file():
        out.append(("Latest legacy research run", RESULTS_DIR))
    if project is not None:
        ref = Path(project).parent / "reference_existing_results"
        if (ref / "summary_by_scenario.csv").is_file():
            out.append(("Legacy reference results (embedded)", ref))
    return out


# --------------------------------------------------------------------------------------
#  exports of the replayed engine runs
# --------------------------------------------------------------------------------------
def write_replay_csv(path, bundles, demand_level, capacity_level, seed):   # demand_level = scenario id
    """One row per engine step per controller; every value is copied from the engine result."""
    with open(path, "w", newline="", encoding="utf-8") as f:
        w = csv.writer(f)
        any_b = next(iter(bundles.values()))
        approaches = any_b.result.approaches
        head = ["status", "controller", "seed", "demand_level", "capacity_level", "step", "time_s", "signal_stage", "phase_id"]
        for a in approaches:
            head += [f"{a}_indication", f"{a}_arrivals", f"{a}_departures", f"{a}_queue_end"]
        w.writerow(head)
        status = any_b.result.labels["status_label"]
        for ctl_name, b in bundles.items():
            r = b.result
            for i, state in enumerate(r.signal_log):
                row = [status, ctl_name, seed, demand_level, capacity_level, i, i * r.dt_seconds, state.stage.value, state.phase_id]
                for a in approaches:
                    row += [state.indication(a), r.arrivals[a][i], r.departures[a][i], r.queue_end[a][i]]
                w.writerow(row)


def write_replay_json(path, bundles, demand_level, capacity_level, seed):
    payload = {"status": next(iter(bundles.values())).result.labels["status_label"],
               "seed": seed, "demand_level": demand_level, "capacity_level": capacity_level, "runs": {}}
    for ctl_name, b in bundles.items():
        payload["runs"][ctl_name] = {"fingerprint_sha256": b.fingerprint, "schedule_sha256": b.schedule_sha,
                                     "metrics": b.metrics, "extended_metrics": b.extended}
    Path(path).write_text(json.dumps(payload, indent=2, default=str), encoding="utf-8")


def write_replay_report(path, bundles, format_report_fn):
    Path(path).write_text("\n\n".join(format_report_fn(b.metrics) for b in bundles.values()) + "\n", encoding="utf-8")


# --------------------------------------------------------------------------------------
#  headless self-test  (python Pachpedi_Naka_Ultra_Visual_Studio.py --selftest)
#  No window is opened.  It checks the engine, the replay and the visual fleet against
#  each other, so every statement the pictures make can be re-verified on your own PC.
# --------------------------------------------------------------------------------------
def run_selftest(out=print, quick=False):
    results = []

    def check(name, ok, detail=""):
        results.append((name, bool(ok), detail))
        out(f"[{'PASS' if ok else 'FAIL'}] {name}" + (f"  -  {detail}" if detail else ""))

    # 1. embedded archive ------------------------------------------------------------------
    raw = base64.b64decode(ENGINE_ZIP_B64)
    check("embedded archive decodes", len(raw) > 1000, f"{len(raw):,} bytes")
    check("embedded archive SHA-256 matches the original", hashlib.sha256(raw).hexdigest() == ENGINE_ZIP_SHA256)
    import io as _io
    with zipfile.ZipFile(_io.BytesIO(raw)) as zf:
        check("embedded archive integrity (zip CRC test)", zf.testzip() is None, f"{len(zf.namelist())} files")

    # 1b. a stale extraction from an older version must be replaced, not reused -------------------------
    global ENGINE_DIR, PROJECT_DIR
    saved = (ENGINE_DIR, PROJECT_DIR)
    with tempfile.TemporaryDirectory() as tmp_stale:
        try:
            ENGINE_DIR = Path(tmp_stale) / "Engine"
            PROJECT_DIR = ENGINE_DIR / "Pachpedi_Naka_Final_Working_Package" / "pachpedi_traffic"
            first = ensure_engine()
            stamped = (ENGINE_DIR / ENGINE_STAMP_NAME).read_text(encoding="utf-8").strip() == ENGINE_ZIP_SHA256
            marker_file = first / "src" / "scenarios.py"
            marker_file.write_text("# OLD ENGINE FROM AN EARLIER VERSION\n", encoding="utf-8")   # simulate an older extraction
            (ENGINE_DIR / ENGINE_STAMP_NAME).unlink()                                            # older versions wrote no stamp
            second = ensure_engine()
            fresh = "RUN_LENGTHS_S" in (second / "src" / "scenarios.py").read_text(encoding="utf-8")
            moved = [p.name for p in Path(tmp_stale).iterdir() if "_replaced_" in p.name]
            check("fresh extraction is stamped with the archive SHA-256", stamped)
            check("stale extraction (no stamp, old code) is replaced by the embedded engine, old folder kept aside", fresh and len(moved) == 1, str(moved))
            marker_file2 = second / "src" / "scenarios.py"
            before = marker_file2.stat().st_mtime_ns
            ensure_engine()
            check("an up-to-date extraction is reused, not re-extracted", marker_file2.stat().st_mtime_ns == before)
        finally:
            ENGINE_DIR, PROJECT_DIR = saved

    # 2. engine ----------------------------------------------------------------------------
    engine = EngineAdapter()
    try:
        engine.load()
    except EngineUnavailable as exc:
        check("engine loads", False, str(exc))
        return results
    check("engine loads from the embedded package", True, str(engine.project))

    scenarios = [("low", "baseline_capacity"), ("medium", "baseline_capacity"), ("high", "baseline_capacity"),
                 ("high", "low_capacity"), ("surge", "baseline_capacity"), ("persistent_east", "baseline_capacity")]
    bundle_cache = {}
    for demand, capacity in scenarios:
        pair = engine.build_runs(demand, capacity, 100)
        bundle_cache[(demand, capacity)] = pair
        check(f"{demand}/{capacity}: all five controllers received the identical arrival schedule (SHA-256) and arrival count",
              len({b.schedule_sha for b in pair.values()}) == 1 and len({b.extended["arrived"] for b in pair.values()}) == 1,
              next(iter(pair.values())).schedule_sha[:12])
        check(f"{demand}/{capacity}: extended metrics report zero conservation violations",
              all(b.extended["conservation_violations"] == 0 for b in pair.values()))
        ad = pair["adaptive_pressure"]
        check(f"{demand}/{capacity}: adaptive controller keeps a decision log with a reason for every decision",
              ad.decisions and all(d["reason"] for d in ad.decisions), f"{len(ad.decisions)} decisions")
        for ctl_name, b in pair.items():
            tag = f"{ctl_name}/{demand}/{capacity}"
            r, tl, m = b.result, b.timeline, b.metrics
            check(f"{tag}: engine validators clean (conservation, no conflicting greens, legal transitions)", not b.issues, "; ".join(b.issues))
            # vehicles are only released during a GREEN step for their own approach
            bad = 0
            for s in r.served:
                step = int((s.departure_time_s - tl.dt) // tl.dt)
                if r.signal_log[step].indication(s.approach_id) != "GREEN":
                    bad += 1
            check(f"{tag}: every served vehicle was served in a GREEN step of its own approach", bad == 0, f"{len(r.served)} vehicles, {bad} violations")
            snap = tl.snapshot(tl.duration)
            check(f"{tag}: replay totals equal engine totals",
                  snap["arrived"] == m["totals"]["total_arrivals"] and snap["served"] == m["totals"]["total_departures"]
                  and snap["waiting"] == m["totals"]["vehicles_remaining_at_end"])
            mw = m["served_wait"]["mean_seconds"]
            check(f"{tag}: replay mean wait equals engine mean wait", (snap["mean_wait"] is None and mw is None) or abs(snap["mean_wait"] - mw) < 1e-9)
            check(f"{tag}: replay max queue equals engine max queue",
                  snap["max_queue"] == max(v["max_queue_vehicles"] for v in m["by_approach"].values()))

    # 2b. selectable run length (15 / 30 / 60 minutes) -----------------------------------------------
    for seconds in (900, 1800):
        runs = engine.build_runs("surge", "baseline_capacity", 100, seconds)
        tag = f"run length {seconds} s"
        check(tag + ": every controller ran exactly that long with zero validator issues",
              all(b.timeline.duration == seconds and b.result.n_steps == seconds and not b.issues for b in runs.values()))
        check(tag + ": identical arrival schedule for all five controllers", len({b.schedule_sha for b in runs.values()}) == 1)
        check(tag + ": replay totals equal engine totals and conservation holds",
              all(b.timeline.snapshot(seconds)["arrived"] == b.metrics["totals"]["total_arrivals"] and b.extended["conservation_violations"] == 0 for b in runs.values()))
    try:
        engine.build_runs("medium", "baseline_capacity", 100, 1000)
        check("invalid run length is rejected", False)
    except ValueError:
        check("invalid run length is rejected", True)

    # 3. visual fleet ----------------------------------------------------------------------
    def play(bundle, speed, until, fps=30.0):
        tl, fleet = bundle.timeline, VisualFleet(bundle.timeline)
        clock = PlaybackClock()
        clock.load(until)
        clock.set_speed(speed)
        now = 0.0
        clock.play(now)
        prev_front, prev_u = {}, {}
        stats = {"frames": 0, "same_lane_overlap": 0, "cross_overlap": 0, "queued_over_line": 0, "jump": 0,
                 "cross_GREEN": 0, "cross_YELLOW": 0, "cross_RED": 0, "max_tracked": 0}
        while clock.state == PlaybackClock.PLAYING:
            now += 1.0 / fps
            t_prev = clock.t
            _, t = clock.tick(now)
            fleet.step(t)
            stats["frames"] += 1
            rects, tracked = [], 0
            for d, st in fleet.states.items():
                tracked += len(st)
                for lane in (0, 1):
                    us = sorted((s.u for s in st.values() if s.lane == lane), reverse=True)
                    for a_, b_ in zip(us, us[1:]):
                        if a_ - b_ < Geo.CAR_L - 0.01:
                            stats["same_lane_overlap"] += 1
                for o, s in st.items():
                    front = s.u + Geo.CAR_L / 2
                    if not s.released and front > Geo.STOP_LINE_U + 0.5:
                        stats["queued_over_line"] += 1
                    key = (d, o)
                    if key in prev_front:
                        if prev_front[key] <= Geo.STOP_LINE_U < front and s.released:
                            # exact crossing instant inside the frame (not the frame end)
                            t_cross = t_prev + (t - t_prev) * (Geo.STOP_LINE_U - prev_front[key]) / (front - prev_front[key])
                            stats["cross_" + tl.indication(tl.by_dir[d], t_cross)] += 1
                        if abs(s.u - prev_u[key]) > Geo.VMAX * (speed / fps) * 1.02 + 1.0:
                            stats["jump"] += 1
                    prev_front[key], prev_u[key] = front, s.u
                    if -60 < s.u < Geo.U_EXIT[d]:
                        rects.append((d, VisualFleet.rect(d, s)))
            for k in [k for k in prev_front if k[1] not in fleet.states[k[0]]]:
                prev_front.pop(k, None)
                prev_u.pop(k, None)
            for i in range(len(rects)):
                di, ri = rects[i]
                for j in range(i + 1, len(rects)):
                    dj, rj = rects[j]
                    if di != dj and ri[0] < rj[2] and rj[0] < ri[2] and ri[1] < rj[3] and rj[1] < ri[3]:
                        stats["cross_overlap"] += 1
            stats["max_tracked"] = max(stats["max_tracked"], tracked)
        return stats

    horizon = 900 if quick else 3600
    for ctl_name in ("fixed_time", "adaptive_pressure"):
        for speed in ((8.0,) if quick else (2.0, 8.0, 32.0)):
            until = min(horizon, 600) if speed <= 2.0 else horizon
            b = bundle_cache[("high", "baseline_capacity")][ctl_name]
            st = play(b, speed, until)
            tag = f"visual fleet {ctl_name} high demand {speed:g}x ({st['frames']:,} frames)"
            check(tag + ": no vehicles overlap in a lane", st["same_lane_overlap"] == 0, f"{st['same_lane_overlap']} overlaps")
            check(tag + ": no vehicles from different approaches collide in the junction", st["cross_overlap"] == 0, f"{st['cross_overlap']} collisions")
            check(tag + ": waiting vehicles never pass the stop line", st["queued_over_line"] == 0, f"{st['queued_over_line']} cases")
            check(tag + ": no vehicle teleports (per-frame travel within physical limit)", st["jump"] == 0, f"{st['jump']} cases")
            check(tag + ": stop-line crossings happen on GREEN/YELLOW only, never on RED", st["cross_RED"] == 0,
                  f"green={st['cross_GREEN']} yellow={st['cross_YELLOW']} red={st['cross_RED']}")
            check(tag + ": tracked vehicle objects bounded", st["max_tracked"] < 4 * 2 * Geo.MAX_ROWS + 80, f"max {st['max_tracked']}")

    # 4. animation cannot alter results ----------------------------------------------------
    unchanged = all(b.verify() for pair in bundle_cache.values() for b in pair.values())
    check("simulation results unchanged after replaying at several speeds (SHA-256 fingerprints)", unchanged)

    # 5. clock behaviour -------------------------------------------------------------------
    c = PlaybackClock()
    c.load(100.0)
    c.set_speed(10.0)
    ok = c.play(0.0) and not c.play(0.0)                 # a second Start click is ignored
    c.tick(0.05)
    t1 = c.t
    ok = ok and abs(t1 - 0.5) < 1e-9 and c.pause() and not c.pause()
    c.tick(5.0)
    ok = ok and c.t == t1                                # paused time does not advance
    c.play(6.0)
    c.tick(60.0)                                         # a 54 s stall is clamped
    ok = ok and abs(c.t - (t1 + 1.0)) < 1e-9
    c.seek(100.0)
    ok = ok and c.state == PlaybackClock.FINISHED
    c.reset()
    ok = ok and c.t == 0.0 and c.state == PlaybackClock.READY
    check("playback clock: start/pause/resume/reset/seek and repeated clicks", ok)

    # 6. export round trip -----------------------------------------------------------------
    with tempfile.TemporaryDirectory() as tmp:
        pair = bundle_cache[("medium", "baseline_capacity")]
        p = Path(tmp) / "replay.csv"
        write_replay_csv(p, pair, "medium", "baseline_capacity", 100)
        with p.open(newline="", encoding="utf-8") as f:
            rows = list(csv.DictReader(f))
        r_fixed = pair["fixed_time"].result
        mine = [int(r["APP_N_queue_end"]) for r in rows if r["controller"] == "fixed_time"]
        check("CSV export equals engine queue log", mine == list(r_fixed.queue_end["APP_N"]) and len(rows) == len(pair) * r_fixed.n_steps)
        write_replay_json(Path(tmp) / "m.json", pair, "medium", "baseline_capacity", 100)
        data = json.loads((Path(tmp) / "m.json").read_text(encoding="utf-8"))
        check("JSON export contains all five controllers", set(data["runs"]) == set(engine.bm.CONTROLLERS))
        write_replay_report(Path(tmp) / "r.txt", pair, engine.met.format_report)
        check("text report export", (Path(tmp) / "r.txt").stat().st_size > 500)

    # 7. shipped results are reproducible ------------------------------------------------------------------
    try:
        emb = Path(engine.project) / "outputs" / "benchmark"
        br = load_benchmark_folder(emb)
        check("embedded benchmark tables load", len(br.summary) > 50 and len(br.paired) > 100,
              f"{len(br.summary)} summary rows, {len(br.paired)} paired rows, {br.metadata.get('n_seeds')} seeds")
        with (emb / "individual_runs.csv").open(newline="", encoding="utf-8") as f:
            rows = list(csv.DictReader(f))
        fresh = engine.build_runs("medium", "baseline_capacity", 100)
        ok = True
        for ctl_name in engine.bm.CONTROLLERS:
            row = next(r for r in rows if r["scenario"] == "medium" and r["capacity_level"] == "baseline_capacity" and r["seed"] == "100" and r["controller"] == ctl_name)
            ok = ok and abs(float(row["all_mean_wait_s"]) - fresh[ctl_name].extended["all_mean_wait_s"]) < 1e-9 and int(row["switches"]) == fresh[ctl_name].extended["switches"]
        check("engine reproduces the shipped benchmark rows for all five controllers (medium demand, seed 100)", ok)
        ref = Path(engine.project).parent / "reference_existing_results"
        er = load_results_folder(ref)
        row = engine.fp_legacy.run_one(engine.base, engine.profile, 100, "fixed_time", "medium", 1.0, "baseline_capacity", 1.0)
        with (ref / "individual_runs.csv").open(newline="", encoding="utf-8") as f:
            match = next(r for r in csv.DictReader(f) if r["seed"] == "100" and r["controller"] == "fixed_time"
                         and r["demand_level"] == "medium" and r["capacity_level"] == "baseline_capacity")
        check("legacy pipeline still reproduces its shipped reference run (seed 100, fixed-time, medium)",
              len(er.summary) == 18 and abs(float(match["mean_wait_seconds"]) - row["mean_wait_seconds"]) < 1e-8)
    except Exception as exc:                              # pragma: no cover
        check("shipped results", False, str(exc))

    failed = [r for r in results if not r[1]]
    out(f"\n{len(results) - len(failed)} passed, {len(failed)} failed")
    return results


# --------------------------------------------------------------------------------------
#  reusable widgets
# --------------------------------------------------------------------------------------
class ScrollFrame(tk.Frame):
    """Vertically scrolling container so no control is ever clipped at small window sizes."""

    def __init__(self, parent, bg):
        super().__init__(parent, bg=bg)
        self.canvas = tk.Canvas(self, bg=bg, highlightthickness=0, bd=0)
        self.vsb = ttk.Scrollbar(self, orient="vertical", command=self.canvas.yview)
        self.inner = tk.Frame(self.canvas, bg=bg)
        self._win = self.canvas.create_window((0, 0), window=self.inner, anchor="nw")
        self.canvas.configure(yscrollcommand=self.vsb.set)
        self.canvas.pack(side="left", fill="both", expand=True)
        self.vsb.pack(side="right", fill="y")
        self.inner.bind("<Configure>", lambda e: self.canvas.configure(scrollregion=self.canvas.bbox("all")))
        self.canvas.bind("<Configure>", lambda e: self.canvas.itemconfigure(self._win, width=e.width))
        self.canvas.bind("<Enter>", self._bind_wheel)
        self.canvas.bind("<Leave>", self._unbind_wheel)
        self.inner.bind("<Enter>", self._bind_wheel)

    def _bind_wheel(self, _e=None):
        self.canvas.bind_all("<MouseWheel>", self._wheel)
        self.canvas.bind_all("<Button-4>", self._wheel)
        self.canvas.bind_all("<Button-5>", self._wheel)

    def _unbind_wheel(self, _e=None):
        for seq in ("<MouseWheel>", "<Button-4>", "<Button-5>"):
            self.canvas.unbind_all(seq)

    def _wheel(self, e):
        if self.inner.winfo_height() <= self.canvas.winfo_height():
            return
        step = -1 if (getattr(e, "num", 0) == 4 or getattr(e, "delta", 0) > 0) else 1
        self.canvas.yview_scroll(step * 2, "units")


class ChartBase(tk.Canvas):
    """Canvas that redraws itself (debounced) when resized and never after it is destroyed."""

    def __init__(self, parent, fonts, height=200):
        super().__init__(parent, bg=THEME["panel"], highlightthickness=1, highlightbackground=THEME["border"],
                         bd=0, height=height)
        self.fonts = fonts
        self._job, self._alive = None, True
        self.bind("<Configure>", lambda e: self.request_redraw())
        self.bind("<Destroy>", self._on_destroy, add="+")

    def _on_destroy(self, event):
        if event.widget is self:
            self._alive = False
            if self._job is not None:
                try:
                    self.after_cancel(self._job)
                except (tk.TclError, ValueError):
                    pass
                self._job = None

    def request_redraw(self, delay=40):
        if self._alive and self._job is None:
            self._job = self.after(delay, self._run_redraw)

    def _run_redraw(self):
        self._job = None
        if not self._alive:
            return
        try:
            if self.winfo_width() > 60 and self.winfo_height() > 50:
                self.redraw()
        except tk.TclError:
            pass

    def redraw(self):                                  # pragma: no cover - overridden
        pass

    def font(self, size, bold=False):
        return (self.fonts["ui"], size, "bold") if bold else (self.fonts["ui"], size)

    def empty_message(self, text):
        self.create_text(self.winfo_width() / 2, self.winfo_height() / 2, text=text, fill=THEME["faint"],
                         font=self.font(10), justify="center")


class _LegendMixin:
    """Legend that wraps onto extra rows instead of running off the chart."""

    def _measure(self, text, size=9):
        if not hasattr(self, "_mf"):
            self._mf = tkfont.Font(root=self, family=self.fonts["ui"], size=size)
        return self._mf.measure(text)

    def _legend(self, names, width):
        pos, x, row = [], self.PAD_L + 4, 0
        for n in names:
            iw = 24 + self._measure(n) + 12
            if x + iw > width - 10 and x > self.PAD_L + 4:
                row, x = row + 1, self.PAD_L + 4
            pos.append((x, row))
            x += iw + 8
        return pos, row + 1

    def _note(self, w, h, text):
        if text:
            self.create_text(w - 10, h - 3, anchor="se", text=text, fill=THEME["faint"], font=self.font(8))


class LineChart(_LegendMixin, ChartBase):
    PAD_L, PAD_R, PAD_T, PAD_B = 56, 16, 46, 36
    MAX_POINTS = 900

    def __init__(self, parent, fonts, height=200):
        super().__init__(parent, fonts, height)
        self.title, self.series, self.xmax, self.ylabel, self.note = "", [], 1.0, "", ""
        self.cursor_x, self._geom = None, None

    def set_data(self, title, series, xmax, ylabel="", note=""):
        self.title, self.series, self.xmax, self.ylabel, self.note = title, series, max(1.0, float(xmax)), ylabel, note
        self.request_redraw(1)

    def redraw(self):
        self.delete("all")
        w, h = self.winfo_width(), self.winfo_height()
        self.create_text(12, 14, anchor="w", text=self.title, fill=THEME["text"], font=self.font(10, True))
        if not self.series or not any(s["ys"] for s in self.series):
            self.empty_message("No run loaded")
            return
        pos, rows = self._legend([s["name"] for s in self.series], w)
        x0, x1, y0, y1 = self.PAD_L, w - self.PAD_R, max(self.PAD_T, 30 + rows * 16 + 6), h - self.PAD_B
        ymax = max((max(s["ys"]) for s in self.series if s["ys"]), default=0)
        yticks = nice_ticks(0, (ymax if ymax > 0 else 1) * 1.05, 4)
        ytop = yticks[-1]
        fx = lambda x: x0 + (x / self.xmax) * (x1 - x0)
        fy = lambda y: y1 - (y / ytop) * (y1 - y0)
        for tv in yticks:
            self.create_line(x0, fy(tv), x1, fy(tv), fill=THEME["border"])
            self.create_text(x0 - 6, fy(tv), anchor="e", text=f"{tv:g}", fill=THEME["dim"], font=self.font(8))
        for tv in nice_ticks(0, self.xmax, 6):
            if 0 <= tv <= self.xmax:
                self.create_line(fx(tv), y1, fx(tv), y1 + 4, fill=THEME["faint"])
                self.create_text(fx(tv), y1 + 6, anchor="n", text=fmt_clock(tv), fill=THEME["dim"], font=self.font(8))
        self.create_line(x0, y0, x0, y1, fill=THEME["faint"])
        self.create_line(x0, y1, x1, y1, fill=THEME["faint"])
        if self.ylabel:
            self.create_text(x0 - 6, y0 - 9, anchor="e", text=self.ylabel, fill=THEME["faint"], font=self.font(8))
        for s, (lx, row) in zip(self.series, pos):
            ly = 32 + row * 16
            self.create_line(lx, ly, lx + 16, ly, fill=s["color"], width=3)
            self.create_text(lx + 22, ly, anchor="w", text=s["name"], fill=THEME["dim"], font=self.font(9))
            if not s["xs"]:
                continue
            stride = max(1, int(math.ceil(len(s["xs"]) / self.MAX_POINTS)))
            idx = list(range(0, len(s["xs"]), stride))
            if idx[-1] != len(s["xs"]) - 1:
                idx.append(len(s["xs"]) - 1)
            pts = []
            for i in idx:
                pts += [fx(s["xs"][i]), fy(s["ys"][i])]
            if len(pts) >= 4:
                self.create_line(*pts, fill=s["color"], width=2, joinstyle="round")
        self._note(w, h, self.note)
        self._geom = (x0, x1, y0, y1, ytop)
        self.set_cursor(self.cursor_x)

    def set_cursor(self, x):
        self.cursor_x = x
        self.delete("cursor")
        if x is None or not self._geom or not self.series:
            return
        x0, x1, y0, y1, ytop = self._geom
        cx = x0 + (max(0.0, min(x, self.xmax)) / self.xmax) * (x1 - x0)
        self.create_line(cx, y0, cx, y1, fill=THEME["cyan"], dash=(3, 3), tags="cursor")
        for s in self.series:
            if not s["xs"]:
                continue
            i = bisect.bisect_right(s["xs"], x) - 1
            if i < 0:
                continue
            cy = y1 - (s["ys"][i] / ytop) * (y1 - y0)
            self.create_oval(cx - 3.5, cy - 3.5, cx + 3.5, cy + 3.5, fill=s["color"], outline=THEME["bg0"], tags="cursor")


class BarChart(_LegendMixin, ChartBase):
    PAD_L, PAD_R, PAD_T, PAD_B = 56, 16, 46, 40

    def __init__(self, parent, fonts, height=200):
        super().__init__(parent, fonts, height)
        self.title, self.categories, self.series, self.ylabel, self.fmt, self.note = "", [], [], "", "{:.1f}", ""

    def set_data(self, title, categories, series, ylabel="", fmt="{:.1f}", note=""):
        self.title, self.categories, self.series, self.ylabel, self.fmt, self.note = title, categories, series, ylabel, fmt, note
        self.request_redraw(1)

    def redraw(self):
        self.delete("all")
        w, h = self.winfo_width(), self.winfo_height()
        self.create_text(12, 14, anchor="w", text=self.title, fill=THEME["text"], font=self.font(10, True))
        values = [v for s in self.series for v in s["values"] if v is not None]
        if not self.categories or not values:
            self.empty_message("No data available")
            return
        pos, rows = self._legend([s["name"] for s in self.series], w)
        x0, x1, y0, y1 = self.PAD_L, w - self.PAD_R, max(self.PAD_T, 30 + rows * 16 + 14), h - self.PAD_B
        lo, hi = min(0.0, min(values)), max(max(values), 1e-9)
        yticks = nice_ticks(lo * 1.12 if lo < 0 else 0, hi * 1.12, 4)
        ybot, ytop = yticks[0], yticks[-1]
        fy = lambda y: y1 - ((y - ybot) / (ytop - ybot)) * (y1 - y0)
        for tv in yticks:
            self.create_line(x0, fy(tv), x1, fy(tv), fill=THEME["border"])
            self.create_text(x0 - 6, fy(tv), anchor="e", text=f"{tv:g}", fill=THEME["dim"], font=self.font(8))
        self.create_line(x0, fy(0), x1, fy(0), fill=THEME["faint"])
        if self.ylabel:
            self.create_text(x0 - 6, y0 - 9, anchor="e", text=self.ylabel, fill=THEME["faint"], font=self.font(8))
        for s, (lx, row) in zip(self.series, pos):
            ly = 32 + row * 16
            self.create_rectangle(lx, ly - 5, lx + 12, ly + 5, fill=s["color"], outline="")
            self.create_text(lx + 18, ly, anchor="w", text=s["name"], fill=THEME["dim"], font=self.font(9))
        n, m = len(self.categories), max(1, len(self.series))
        slot = (x1 - x0) / n
        bar_w = min(46.0, slot * 0.72 / m)
        for ci, cat in enumerate(self.categories):
            gx = x0 + slot * ci + slot / 2
            self.create_text(gx, y1 + 7, anchor="n", text=cat, fill=THEME["dim"], font=self.font(8 if n > 4 else 9), width=max(40, slot - 4), justify="center")
            for si, s in enumerate(self.series):
                v = s["values"][ci]
                bx = gx - (m * bar_w) / 2 + si * bar_w
                if v is None:
                    self.create_text(bx + bar_w / 2, y1 - 8, text="n/a", fill=THEME["faint"], font=self.font(8))
                    continue
                top, zero = fy(v), fy(0)
                self.create_rectangle(bx + 1, min(top, zero), bx + bar_w - 1, max(top, zero), fill=s["color"], outline="")
                self.create_text(bx + bar_w / 2, (top - 8) if v >= 0 else (top + 8), text=self.fmt.format(v), fill=THEME["text"], font=self.font(8))
        self._note(w, h, self.note)


class TimelineStrip(ChartBase):
    """Signal phase history: one row per approach, coloured by the engine's recorded signal log."""
    COLORS = {"GREEN": "#1fb75a", "YELLOW": "#f2a516", "RED": "#6b1f2a"}
    MODES = {"Full run": None, "10 min": 600.0, "2 min": 120.0}

    def __init__(self, parent, fonts, height=140):
        super().__init__(parent, fonts, height)
        self.timeline, self.mode, self.t, self.w0, self._geom = None, "2 min", 0.0, 0.0, None

    def set_timeline(self, tl):
        self.timeline, self.t, self.w0 = tl, 0.0, 0.0
        self.request_redraw(1)

    def set_mode(self, mode):
        self.mode = mode if mode in self.MODES else "2 min"
        self.w0 = 0.0
        self._ensure_page()
        self.request_redraw(1)

    def span(self):
        if not self.timeline:
            return 1.0
        s = self.MODES[self.mode]
        return self.timeline.duration if s is None else min(s, self.timeline.duration)

    def _ensure_page(self):
        if not self.timeline:
            return False
        span, old = self.span(), self.w0
        if self.MODES[self.mode] is None:
            self.w0 = 0.0
        elif self.t < self.w0 or self.t > self.w0 + 0.85 * span:
            self.w0 = max(0.0, min(self.t - 0.1 * span, self.timeline.duration - span))
        return self.w0 != old

    def set_time(self, t):
        self.t = t
        if self._ensure_page():
            self.request_redraw(1)
        else:
            self._move_head()

    def _x(self, t):
        x0, x1, span = self._geom
        return x0 + ((t - self.w0) / span) * (x1 - x0)

    def _move_head(self):
        self.delete("head")
        if not self._geom or not self.timeline:
            return
        x = self._x(self.t)
        x0, x1, _ = self._geom
        if x0 <= x <= x1:
            self.create_line(x, 22, x, self.winfo_height() - 20, fill="#ffffff", width=2, tags="head")
            self.create_polygon(x - 5, 18, x + 5, 18, x, 26, fill="#ffffff", outline="", tags="head")

    def redraw(self):
        self.delete("all")
        w, h = self.winfo_width(), self.winfo_height()
        self.create_text(12, 11, anchor="w", text="Signal phase timeline (recorded engine signal log)", fill=THEME["text"], font=self.font(10, True))
        if not self.timeline:
            self.empty_message("No run loaded")
            return
        tl = self.timeline
        x0, x1 = 64, w - 14
        span = self.span()
        self._geom = (x0, x1, span)
        dirs = [tl.dirs[a] for a in tl.approaches]
        order = []
        for pid in tl.phase_order:
            for a in tl.approaches:
                if tl.phase_label[pid] == DIR_NAMES[tl.dirs[a]] and tl.dirs[a] not in order:
                    order.append(tl.dirs[a])
        order += [d for d in dirs if d not in order]
        top, avail = 28, h - 28 - 22
        row_h = max(10, min(24, avail / max(1, len(order))))
        for r, d in enumerate(order):
            y = top + r * row_h
            self.create_text(x0 - 8, y + row_h / 2, anchor="e", text=DIR_NAMES[d], fill=THEME["dim"], font=self.font(9))
            self.create_rectangle(x0, y + 2, x1, y + row_h - 2, fill=THEME["bg2"], outline="")
            a = tl.by_dir[d]
            for t0, t1, color in tl.segments[a]:
                if t1 <= self.w0 or t0 >= self.w0 + span:
                    continue
                xa, xb = self._x(max(t0, self.w0)), self._x(min(t1, self.w0 + span))
                if xb - xa < 0.6:
                    continue
                self.create_rectangle(xa, y + 2, xb, y + row_h - 2, fill=self.COLORS[color], outline="")
        yb = top + len(order) * row_h
        for tv in nice_ticks(self.w0, self.w0 + span, 8):
            if self.w0 <= tv <= self.w0 + span:
                x = self._x(tv)
                self.create_line(x, yb + 1, x, yb + 5, fill=THEME["faint"])
                self.create_text(x, yb + 7, anchor="n", text=fmt_clock(tv), fill=THEME["dim"], font=self.font(8))
        lx = x1
        for name, col in (("stopped", self.COLORS["RED"]), ("amber", self.COLORS["YELLOW"]), ("go", self.COLORS["GREEN"])):
            self.create_text(lx, 11, anchor="e", text=name, fill=THEME["dim"], font=self.font(8))
            lx -= 44 if name != "stopped" else 52
            self.create_rectangle(lx, 6, lx + 10, 16, fill=col, outline="")
            lx -= 14
        self._move_head()


# --------------------------------------------------------------------------------------
#  intersection renderer
# --------------------------------------------------------------------------------------
class IntersectionView:
    """Top-down intersection.  Static road/buildings are drawn once per resize; vehicles use
    a pooled set of canvas items moved with canvas.move(); signal lamps, stop-line glow,
    congestion bars and the HUD are updated only when their value changes."""

    LAMP_ON = {"R": "#ff4d4d", "Y": "#ffb627", "G": "#2ee88a"}
    LAMP_OFF = {"R": "#2a1519", "Y": "#2b2412", "G": "#10281d"}
    BODY = ("#d9e2ec", "#aab7c4", "#7f8ea0", "#e8edf2", "#5f93c9", "#c0504d", "#d6a84a", "#4f6b86")
    HEAD = {"N": ((Geo.CX + 63, Geo.CY - Geo.STOP - 30), "v"), "S": ((Geo.CX - 63, Geo.CY + Geo.STOP + 30), "v"),
            "E": ((Geo.CX + Geo.STOP + 30, Geo.CY + 63), "h"), "W": ((Geo.CX - Geo.STOP - 30, Geo.CY - 63), "h")}
    CHIP = {"N": (Geo.CX + 63, 30), "S": (Geo.CX - 63, Geo.H - 30), "E": (Geo.W - 120, Geo.CY + 63), "W": (120, Geo.CY - 63)}
    FWD = {"N": (0, 1), "S": (0, -1), "E": (-1, 0), "W": (1, 0)}

    def __init__(self, parent, fonts, title):
        self.fonts, self.title = fonts, title
        self.frame = tk.Frame(parent, bg=THEME["bg0"], highlightthickness=1, highlightbackground=THEME["border_hi"])
        self.canvas = tk.Canvas(self.frame, bg=THEME["bg0"], highlightthickness=0, bd=0)
        self.canvas.pack(fill="both", expand=True)
        self.canvas.bind("<Configure>", self._on_configure)
        self.canvas.bind("<Destroy>", self._on_destroy, add="+")
        self.bundle = self.timeline = self.fleet = None
        self.k, self.ox, self.oy, self.cw, self.ch = 1.0, 0.0, 0.0, 0, 0
        self._job, self._alive = None, True
        self.last_t, self.last_speed = 0.0, 1.0
        self._reset_items()

    def _reset_items(self):
        self.vitems, self.lamp_items, self.stop_items, self.heat_items = {}, {}, {}, {}
        self.badge_items, self.chip_items, self.hud_items = {}, {}, {}
        self.lamp = {}
        self.heat_ext = {}
        self._fill, self._text = {}, {}

    # ---- lifecycle ----------------------------------------------------------------
    def destroy(self):
        self._alive = False
        if self._job is not None:
            try:
                self.canvas.after_cancel(self._job)
            except (tk.TclError, ValueError):
                pass
            self._job = None
        try:
            self.frame.destroy()
        except tk.TclError:
            pass

    def _on_destroy(self, event):
        if event.widget is self.canvas:
            self._alive = False

    def _on_configure(self, _event):
        if self._alive and self._job is None:
            self._job = self.canvas.after(60, self._rebuild)

    def set_bundle(self, bundle):
        self.bundle = bundle
        self.timeline = bundle.timeline if bundle else None
        self.fleet = VisualFleet(self.timeline) if bundle else None
        if bundle:
            self.title = CONTROLLER_LABELS.get(bundle.controller, bundle.controller)
            self.fleet.resync(self.last_t)
        self._rebuild()

    def sync(self, t):
        """Jump the visual fleet to time t (after a seek / reset)."""
        self.last_t = t
        if self.fleet:
            self.fleet.resync(t)
        self.render(t, 0.0, self.last_speed, force=True)

    # ---- transforms ---------------------------------------------------------------
    def P(self, x, y):
        return self.ox + x * self.k, self.oy + y * self.k

    def L(self, d, s, u):
        return self.P(*Geo.xy(d, s, u))

    def _poly_local(self, d, pts, **kw):
        flat = []
        for s, u in pts:
            flat += self.L(d, s, u)
        return self.canvas.create_polygon(*flat, **kw)

    def _rectw(self, x1, y1, x2, y2, **kw):
        a, b = self.P(x1, y1), self.P(x2, y2)
        return self.canvas.create_rectangle(a[0], a[1], b[0], b[1], **kw)

    def _linew(self, x1, y1, x2, y2, **kw):
        a, b = self.P(x1, y1), self.P(x2, y2)
        return self.canvas.create_line(a[0], a[1], b[0], b[1], **kw)

    def _ovalw(self, x, y, r, **kw):
        a, b = self.P(x - r, y - r), self.P(x + r, y + r)
        return self.canvas.create_oval(a[0], a[1], b[0], b[1], **kw)

    def _font(self, size, bold=False, scaled=True):
        size = max(7, int(round(size * self.k + 0.5))) if scaled else size
        return (self.fonts["ui"], size, "bold") if bold else (self.fonts["ui"], size)

    # ---- (re)build ----------------------------------------------------------------
    def _rebuild(self):
        self._job = None
        if not self._alive:
            return
        try:
            w, h = self.canvas.winfo_width(), self.canvas.winfo_height()
            if w < 160 or h < 100:
                return
            self.cw, self.ch = w, h
            self.k = min(w / Geo.W, h / Geo.H)
            self.ox, self.oy = (w - Geo.W * self.k) / 2.0, (h - Geo.H * self.k) / 2.0
            self.canvas.delete("all")
            self._reset_items()
            self._draw_static()
            self._create_dynamic()
            self.render(self.last_t, 0.0, self.last_speed, force=True)
        except tk.TclError:
            pass

    def _draw_static(self):
        c, T = self.canvas, THEME
        cx, cy = Geo.CX, Geo.CY
        c.create_rectangle(0, 0, self.cw, self.ch, fill=T["bg0"], outline="")
        self._rectw(0, 0, Geo.W, Geo.H, fill="#07101c", outline="")
        for gx in range(0, int(Geo.W) + 1, 60):
            self._linew(gx, 0, gx, Geo.H, fill="#0a1626")
        for gy in range(0, int(Geo.H) + 1, 60):
            self._linew(0, gy, Geo.W, gy, fill="#0a1626")
        off = Geo.HALF + Geo.WALK + 6
        lots = [(10, 10, cx - off, cy - off, (1, 1)), (cx + off, 10, Geo.W - 10, cy - off, (-1, 1)),
                (10, cy + off, cx - off, Geo.H - 10, (1, -1)), (cx + off, cy + off, Geo.W - 10, Geo.H - 10, (-1, -1))]
        for i, (x1, y1, x2, y2, _) in enumerate(lots):
            self._draw_lot(x1, y1, x2, y2, i, random.Random(4100 + i))
        # sidewalks and carriageways
        for r in ((cx - Geo.HALF - Geo.WALK, 0, cx - Geo.HALF, Geo.H), (cx + Geo.HALF, 0, cx + Geo.HALF + Geo.WALK, Geo.H),
                  (0, cy - Geo.HALF - Geo.WALK, Geo.W, cy - Geo.HALF), (0, cy + Geo.HALF, Geo.W, cy + Geo.HALF + Geo.WALK)):
            self._rectw(*r, fill=T["walk"], outline="")
        self._rectw(cx - Geo.HALF, 0, cx + Geo.HALF, Geo.H, fill=T["asphalt"], outline="")
        self._rectw(0, cy - Geo.HALF, Geo.W, cy + Geo.HALF, fill=T["asphalt"], outline="")
        self._rectw(cx - Geo.HALF, cy - Geo.HALF, cx + Geo.HALF, cy + Geo.HALF, fill=T["asphalt2"], outline="")
        kw = max(1.0, 1.6 * self.k)
        for d in "NSEW":
            A = Geo.ARM[d]
            self._poly_local(d, [(-Geo.MED, -A), (Geo.MED, -A), (Geo.MED, 0), (-Geo.MED, 0)], fill="#0d1722", outline="")
            for s in (-Geo.MED, Geo.MED):
                a, b = self.L(d, s, -A), self.L(d, s, 0)
                c.create_line(*a, *b, fill="#c99a1f", width=kw)
            for s in (-Geo.HALF, Geo.HALF):
                a, b = self.L(d, s, -A), self.L(d, s, Geo.CROSS)
                c.create_line(*a, *b, fill=T["kerb"], width=kw)
            for s in (-Geo.HALF + 3, Geo.HALF - 3):
                a, b = self.L(d, s, -A), self.L(d, s, 0)
                c.create_line(*a, *b, fill="#5f7891", width=max(1.0, self.k))
            for s in (-Geo.MED - Geo.LANE, Geo.MED + Geo.LANE):
                u = -A
                while u < -26:
                    a, b = self.L(d, s, u), self.L(d, s, min(u + 11, -26))
                    c.create_line(*a, *b, fill="#8da2b8", width=max(1.0, self.k))
                    u += 24
            a, b = self.L(d, Geo.MED + 1.5, Geo.STOP_LINE_U), self.L(d, Geo.HALF - 1.5, Geo.STOP_LINE_U)
            c.create_line(*a, *b, fill="#e5eef8", width=max(2.0, 3.0 * self.k))
            s = -Geo.HALF + 6
            while s < Geo.HALF - 6:
                self._poly_local(d, [(s, 3), (s + 6, 3), (s + 6, 21), (s, 21)], fill="#a9bccf", outline="")
                s += 12
            for lane_s in Geo.LANE_OFF:
                u0 = -70
                self._poly_local(d, [(lane_s - 1.6, u0), (lane_s + 1.6, u0), (lane_s + 1.6, u0 + 16), (lane_s + 6, u0 + 16),
                                     (lane_s, u0 + 29), (lane_s - 6, u0 + 16), (lane_s - 1.6, u0 + 16)], fill="#4c657e", outline="")
        c.create_text(*self.P(cx, cy - 7), text="PACHPEDI NAKA", fill="#24415f", font=self._font(10, True))
        c.create_text(*self.P(cx, cy + 9), text="stylised layout", fill="#1d3550", font=self._font(7))
        for y in range(40, int(Geo.H) - 20, 110):
            if abs(y - cy) > 96:
                for x in (cx - 63, cx + 63):
                    self._lamp_post(x, y)
        for x in range(60, int(Geo.W) - 20, 110):
            if abs(x - cx) > 96:
                for y in (cy - 63, cy + 63):
                    self._lamp_post(x, y)

    def _lamp_post(self, x, y):
        self._ovalw(x, y, 7.5, fill="#17202b", outline="")
        self._ovalw(x, y, 2.6, fill="#ffd88a", outline="")

    def _draw_lot(self, x1, y1, x2, y2, idx, rng):
        c = self.canvas
        self._rectw(x1, y1, x2, y2, fill="#091827", outline="#112c44")
        inner = (x2 if idx % 2 == 0 else x1, y2 if idx < 2 else y1)
        cols, rows = 3, 2
        cw, chh = (x2 - x1) / cols, (y2 - y1) / rows
        for ci in range(cols):
            for ri in range(rows):
                gx1, gy1 = x1 + ci * cw, y1 + ri * chh
                if abs((gx1 + cw / 2) - inner[0]) < 160 and abs((gy1 + chh / 2) - inner[1]) < 120:
                    continue
                if rng.random() < 0.15:
                    continue
                bw, bh = cw * rng.uniform(0.55, 0.8), chh * rng.uniform(0.5, 0.75)
                bx, by = gx1 + (cw - bw) / 2 + rng.uniform(-8, 8), gy1 + (chh - bh) / 2 + rng.uniform(-8, 8)
                self._rectw(bx + 6, by + 8, bx + bw + 6, by + bh + 8, fill="#050d17", outline="")
                roof = rng.choice(("#13273d", "#162c45", "#112338", "#18314c"))
                self._rectw(bx, by, bx + bw, by + bh, fill=roof, outline="#27496a")
                self._rectw(bx + 5, by + 5, bx + bw - 5, by + bh - 5, fill=blend(roof, "#ffffff", 0.05), outline="")
                for _ in range(rng.randint(2, 4)):
                    ux, uy = bx + rng.uniform(10, max(11, bw - 22)), by + rng.uniform(10, max(11, bh - 20))
                    self._rectw(ux, uy, ux + rng.uniform(8, 16), uy + rng.uniform(6, 12), fill="#223f5e", outline="")
        step = 42
        for i in range(int((x2 - x1) // step)):
            x = x1 + 14 + i * step + rng.uniform(-4, 4)
            for y in ((y2 - 11) if idx < 2 else (y1 + 11),):
                self._tree(x, y, rng)
        for i in range(int((y2 - y1) // step)):
            y = y1 + 14 + i * step + rng.uniform(-4, 4)
            self._tree(inner[0] + (-11 if idx % 2 == 0 else 11), y, rng)

    def _tree(self, x, y, rng):
        r = rng.uniform(7, 10)
        self._ovalw(x + 2, y + 3, r, fill="#04100f", outline="")
        self._ovalw(x, y, r, fill="#0f3b2e", outline="#155e49")
        self._ovalw(x - r * 0.25, y - r * 0.25, r * 0.45, fill="#1b6b52", outline="")

    # ---- dynamic items ------------------------------------------------------------
    def _create_dynamic(self):
        c, T = self.canvas, THEME
        tl = self.timeline
        dirs = list(tl.by_dir) if tl else list("NSEW")
        for d in dirs:
            a = Geo.MED + 1.5
            glow = c.create_line(*self.L(d, a, Geo.STOP_LINE_U), *self.L(d, Geo.HALF - 1.5, Geo.STOP_LINE_U),
                                 fill=T["asphalt"], width=max(5.0, 9.0 * self.k), capstyle="round", tags="dyn_stop")
            line = c.create_line(*self.L(d, a, Geo.STOP_LINE_U), *self.L(d, Geo.HALF - 1.5, Geo.STOP_LINE_U),
                                 fill="#e5eef8", width=max(2.0, 3.2 * self.k), tags="dyn_stop")
            self.stop_items[d] = (glow, line)
            heat = c.create_line(*self.L(d, Geo.HALF - 5, -4), *self.L(d, Geo.HALF - 5, -5), fill=T["green"],
                                 width=max(2.0, 3.5 * self.k), state="hidden", tags="dyn_heat")
            self.heat_items[d] = heat
            self.heat_ext[d] = 0.0
            bx, by = self.L(d, Geo.MED + Geo.LANE, -(Geo.ARM[d] - 24))
            bg = c.create_rectangle(bx - 24 * self.k - 4, by - 9 * self.k - 3, bx + 24 * self.k + 4, by + 9 * self.k + 3,
                                    fill="#2a1d05", outline=T["amber"], state="hidden", tags="dyn_badge")
            tx = c.create_text(bx, by, text="", fill=T["amber"], font=self._font(9, True), state="hidden", tags="dyn_badge")
            self.badge_items[d] = (bg, tx)
            (hx, hy), orient = self.HEAD[d]
            hw, hh = (9, 25) if orient == "v" else (25, 9)
            c.create_rectangle(*self.P(hx - hw, hy - hh), *self.P(hx + hw, hy + hh), fill="#070d16", outline="#3b5a78", tags="sig")
            self.lamp[d] = {"R": 0.0, "Y": 0.0, "G": 0.0}
            self.lamp_items[d] = {}
            for i, ch in enumerate("RYG"):
                lx, ly = (hx, hy + (i - 1) * 16) if orient == "v" else (hx + (i - 1) * 16, hy)
                h2 = self._ovalw(lx, ly, 15, fill=T["bg0"], outline="", tags="sig")
                h1 = self._ovalw(lx, ly, 10.5, fill=T["bg0"], outline="", tags="sig")
                lp = self._ovalw(lx, ly, 6, fill=self.LAMP_OFF[ch], outline="#000000", tags="sig")
                self.lamp_items[d][ch] = (h2, h1, lp)
            cxp, cyp = self.CHIP[d]
            self.chip_items[d] = c.create_text(*self.P(cxp, cyp), text="", fill=T["dim"], font=self._font(9, True),
                                               justify="center", tags="hud")
        self.hud_items["clock"] = c.create_text(14, 10, anchor="nw", text="", fill=T["text"], font=self._font(12, True, False), tags="hud")
        self.hud_items["phase"] = c.create_text(14, 32, anchor="nw", text="", fill=T["dim"], font=self._font(10, False, False), tags="hud")
        self.hud_items["next"] = c.create_text(14, 50, anchor="nw", text="", fill=T["faint"], font=self._font(9, False, False), tags="hud")
        self.hud_items["title"] = c.create_text(self.cw - 14, 10, anchor="ne", text=self.title, fill=T["cyan"], font=self._font(13, True, False), tags="hud")
        self.hud_items["foot"] = c.create_text(14, self.ch - 8, anchor="sw",
                                               text="Replay of an engine run  |  synthetic inputs  |  stylised layout, lanes and vehicles",
                                               fill=T["faint"], font=self._font(8, False, False), tags="hud")
        c.tag_raise("hud")

    def _set_fill(self, item, color):
        if self._fill.get(item) != color:
            self.canvas.itemconfigure(item, fill=color)
            self._fill[item] = color

    def _set_text(self, item, text, color=None):
        key = (text, color)
        if self._text.get(item) != key:
            if color is None:
                self.canvas.itemconfigure(item, text=text)
            else:
                self.canvas.itemconfigure(item, text=text, fill=color)
            self._text[item] = key

    def _car_items(self, d, x, y):
        k, fx, fy = self.k, *self.FWD[d]
        nx, ny = -fy, fx

        def pts(local):
            out = []
            for a, b in local:
                out += [self.ox + (x + a * fx + b * nx) * k, self.oy + (y + a * fy + b * ny) * k]
            return out

        L2, W2, ch = Geo.CAR_L / 2, Geo.CAR_W / 2, 2.4
        body = [(-L2 + ch, -W2), (L2 - ch, -W2), (L2, -W2 + ch), (L2, W2 - ch), (L2 - ch, W2), (-L2 + ch, W2), (-L2, W2 - ch), (-L2, -W2 + ch)]
        cabin = [(-5.4, -W2 + 1.7), (4.2, -W2 + 1.7), (4.2, W2 - 1.7), (-5.4, W2 - 1.7)]
        return body, cabin, pts

    def _create_car(self, d, o, s, x, y):
        c, k = self.canvas, self.k
        body, cabin, pts = self._car_items(d, x, y)
        tag = f"v{d}{o}"
        color = self.BODY[(o * 7 + ord(d)) % len(self.BODY)]
        L2, W2 = Geo.CAR_L / 2, Geo.CAR_W / 2
        c.create_polygon(*[v + (1.3 * k if i % 2 == 0 else 1.9 * k) for i, v in enumerate(pts(body))], fill="#03080f", outline="", tags=(tag, "veh"))
        c.create_polygon(*pts(body), fill=color, outline=blend(color, "#000000", 0.45), tags=(tag, "veh"))
        c.create_polygon(*pts(cabin), fill=blend("#0a1a2a", color, 0.12), outline="", tags=(tag, "veh"))
        c.create_line(*pts([(L2 - 0.9, -4.0), (L2 - 0.9, 4.0)]), fill="#fff0c0", width=max(1.0, 1.6 * k), tags=(tag, "veh"))
        tail = c.create_line(*pts([(-L2 + 0.9, -4.0), (-L2 + 0.9, 4.0)]), fill="#ff3b3b" if s.brake else "#6d1c24",
                             width=max(1.0, 1.8 * k), tags=(tag, "veh"))
        c.tag_lower(tag, "sig")
        self.vitems[(d, o)] = {"tag": tag, "x": x, "y": y, "brake": s.brake, "tail": tail}

    # ---- per-frame update ---------------------------------------------------------
    def render(self, t, wall_dt, speed, force=False):
        self.last_t, self.last_speed = t, speed
        if not self._alive or not self.timeline or not self.stop_items or not self.cw:
            return
        try:
            self._render(t, wall_dt, speed, force)
        except tk.TclError:
            pass

    def _render(self, t, wall_dt, speed, force):
        c, tl, k, T = self.canvas, self.timeline, self.k, THEME
        self.fleet.step(t)
        snap = tl.snapshot(t)
        tau = 0.10 if speed <= 4 else max(0.012, 0.40 / speed)
        f = 1.0 if force else 1.0 - math.exp(-max(0.0, wall_dt) / tau)
        hf = 1.0 if force else 1.0 - math.exp(-max(0.0, wall_dt) / 0.25)
        for d, a in tl.by_dir.items():
            ind = tl.indication(a, t)
            target = {"R": ind == "RED", "Y": ind == "YELLOW", "G": ind == "GREEN"}
            lv = self.lamp[d]
            for ch in "RYG":
                tv = 1.0 if target[ch] else 0.0
                lv[ch] += (tv - lv[ch]) * f
                if abs(tv - lv[ch]) < 0.01:
                    lv[ch] = tv
                h2, h1, lp = self.lamp_items[d][ch]
                self._set_fill(lp, blend(self.LAMP_OFF[ch], self.LAMP_ON[ch], lv[ch]))
                self._set_fill(h1, blend(T["bg0"], self.LAMP_ON[ch], lv[ch] * 0.34))
                self._set_fill(h2, blend(T["bg0"], self.LAMP_ON[ch], lv[ch] * 0.14))
            base = "#cbd5e1"
            col, glow = base, T["asphalt"]
            for ch in "RYG":
                col = blend(col, self.LAMP_ON[ch], lv[ch] * 0.9)
                glow = blend(glow, self.LAMP_ON[ch], lv[ch] * 0.42)
            self._set_fill(self.stop_items[d][1], col)
            self._set_fill(self.stop_items[d][0], glow)
            q, state = snap["queue_by_dir"][d], {"GREEN": "GO", "YELLOW": "AMBER", "RED": "STOP"}[ind]
            chip_col = {"GREEN": T["green"], "YELLOW": T["amber"], "RED": "#e0707c"}[ind]
            self._set_text(self.chip_items[d], f"{DIR_NAMES[d].upper()}  {state}\n{q} waiting", chip_col)
        seen = set()
        for d, st in self.fleet.states.items():
            for o, s in st.items():
                if not VisualFleet.on_screen(d, s):
                    continue
                key = (d, o)
                seen.add(key)
                x, y = VisualFleet.centre_xy(d, s)
                it = self.vitems.get(key)
                if it is None:
                    self._create_car(d, o, s, x, y)
                    continue
                dx, dy = (x - it["x"]) * k, (y - it["y"]) * k
                if abs(dx) > 0.02 or abs(dy) > 0.02:
                    c.move(it["tag"], dx, dy)
                    it["x"], it["y"] = x, y
                if it["brake"] != s.brake:
                    c.itemconfigure(it["tail"], fill="#ff3b3b" if s.brake else "#6d1c24")
                    it["brake"] = s.brake
        for key in [kk for kk in self.vitems if kk not in seen]:
            c.delete(self.vitems.pop(key)["tag"])
        for d, a in tl.by_dir.items():
            vq = tl.visual_queue(a, t)
            rows = (vq + 1) // 2
            tgt = min(Geo.ARM[d] - 30.0, Geo.FRONT_GAP + rows * Geo.SLOT) if vq > 0 else 0.0
            ext = self.heat_ext[d] + (tgt - self.heat_ext[d]) * hf
            if abs(ext - tgt) < 0.5:
                ext = tgt
            if abs(ext - self.heat_ext[d]) > 0.2 or force:
                self.heat_ext[d] = ext
                item = self.heat_items[d]
                if ext < 1.0:
                    c.itemconfigure(item, state="hidden")
                else:
                    c.coords(item, *self.L(d, Geo.HALF - 5, -4), *self.L(d, Geo.HALF - 5, -4 - ext))
                    c.itemconfigure(item, state="normal", fill=T["green"] if vq < 7 else T["amber"] if vq < 16 else T["red"])
            hidden = vq - 2 * Geo.visible_rows(d)
            bg, tx = self.badge_items[d]
            if hidden > 0:
                self._set_text(tx, f"+{hidden} more")
                c.itemconfigure(bg, state="normal")
                c.itemconfigure(tx, state="normal")
            else:
                c.itemconfigure(bg, state="hidden")
                c.itemconfigure(tx, state="hidden")
        stage_col = {"GREEN": T["green"], "YELLOW": T["amber"], "ALL_RED": "#e0707c"}[snap["stage"]]
        narrow = self.cw < 700
        self._set_text(self.hud_items["clock"], f"{fmt_clock(t)} / {fmt_clock(tl.duration)}" + ("" if narrow else f"    step {snap['step'] + 1:,} of {tl.n_steps:,}"))
        stage_name = {"GREEN": "Green", "YELLOW": "Amber", "ALL_RED": "All red"}[snap["stage"]]
        self._set_text(self.hud_items["phase"], f"{stage_name}: {snap['phase_label']}   {snap['stage_ends_in']:.0f} s left" + ("" if narrow else " (recorded)"), stage_col)
        nxt = snap["next_phase_label"]
        self._set_text(self.hud_items["next"], f"Next green: {nxt}" if nxt else "Next green: none before end of run")


# --------------------------------------------------------------------------------------
#  diagnostics log
# --------------------------------------------------------------------------------------
class DiagLog:
    MAX_LINES = 700

    def __init__(self, parent, fonts):
        self.text = ScrolledText(parent, height=5, bg=THEME["bg0"], fg=THEME["dim"], font=(fonts["mono"], 9),
                                 relief="flat", wrap="word", state="disabled", highlightthickness=1,
                                 highlightbackground=THEME["border"], insertbackground=THEME["text"], bd=0, padx=8, pady=4)
        for tag, color in (("info", THEME["dim"]), ("ok", THEME["green"]), ("warn", THEME["amber"]),
                           ("error", "#ff7b7b"), ("dim", THEME["faint"]), ("time", THEME["faint"])):
            self.text.tag_configure(tag, foreground=color)

    def log(self, level, message):
        try:
            stamp = datetime.datetime.now().strftime("%H:%M:%S")
            self.text.configure(state="normal")
            self.text.insert("end", stamp + "  ", "time")
            self.text.insert("end", f"{level.upper():5s} ", level if level in ("ok", "warn", "error") else "info")
            self.text.insert("end", message + "\n", level if level in ("ok", "warn", "error", "dim") else "info")
            lines = int(self.text.index("end-1c").split(".")[0])
            if lines > self.MAX_LINES:
                self.text.delete("1.0", f"{lines - self.MAX_LINES}.0")
            self.text.see("end")
            self.text.configure(state="disabled")
        except tk.TclError:
            pass


# --------------------------------------------------------------------------------------
#  the Studio window
# --------------------------------------------------------------------------------------
class UltraStudioApp(App):
    """New command-centre window.  Derives from the original App so that the original
    research launcher, results-folder opener and snapshot export are reused unchanged."""

    FRAME_MS = 16
    FIXED_COLOR, RESP_COLOR = "#f5a524", "#22d3ee"

    def __init__(self):
        tk.Tk.__init__(self)                       # original App.__init__ would build the old window
        self.title(STUDIO_TITLE)
        self.geometry("1540x940")
        self.minsize(1200, 780)
        self.configure(bg=THEME["bg0"])
        self._closing = False
        self.fonts = {"ui": pick_font_family("Segoe UI", ("Helvetica", "DejaVu Sans", "Arial")),
                      "mono": pick_font_family("Consolas", ("DejaVu Sans Mono", "Courier New", "Courier"))}
        # names used by the inherited original methods
        self.mode = tk.StringVar(value="queue_responsive")
        self.demand = tk.StringVar(value="Medium")
        self.seed_count = tk.StringVar(value="10")
        self.bootstrap_count = tk.StringVar(value="10000")
        self.status = tk.StringVar(value="Starting...")
        self.classic_status = tk.StringVar(value="")
        self.stat_vars = {"passed": tk.StringVar(value="0"), "waiting": tk.StringVar(value="20"),
                          "queues": tk.StringVar(value="N 5  |  S 5  |  E 5  |  W 5")}
        # studio state
        self.v_focus = tk.StringVar(value="adaptive_pressure")
        self.v_view = tk.StringVar(value="single")
        self.v_scenario = tk.StringVar(value=SCENARIO_LABELS["medium"])
        self.v_focus_label = tk.StringVar(value=CONTROLLER_LABELS["adaptive_pressure"])
        self.v_compare = tk.StringVar(value=CONTROLLER_LABELS["fixed_time"])
        self.v_capacity = tk.StringVar(value=CAPACITY_LABELS["baseline_capacity"])
        self.v_seed = tk.StringVar(value="100")
        self.v_runtime = tk.StringVar(value=RUNTIME_LABELS[3600])
        self.run_seconds = 3600
        self.v_speed = tk.StringVar(value="2x")
        self.v_window = tk.StringVar(value="2 min")
        self.v_source = tk.StringVar(value="")
        self.engine = EngineAdapter()
        self.bundles, self.params = {}, None
        self.clock = PlaybackClock()
        self.views, self.results, self._sources = [], None, {}
        self._after_id, self._last_frame, self._last_metrics = None, 0.0, 0.0
        self._render_ms, self._fps_stamp, self._fps_count, self._fps = 0.0, time.perf_counter(), 0, 0.0
        self._slider_programmatic, self._dragging, self._research_running, self._research_kind = False, False, False, None
        self._fig_index, self._fig_image = 0, None
        self._label_cache, self._board_items, self._board_disp = {}, {}, {}
        self._board_cache = {}
        self._style()
        self.build_ui()
        self.protocol("WM_DELETE_WINDOW", self.on_close)
        self.bind("<space>", self._key_space)
        self.bind("<Left>", lambda e: self._key_seek(-10))
        self.bind("<Right>", lambda e: self._key_seek(10))
        self.status.trace_add("write", self._mirror_status)
        self.after(120, self._startup)

    # ---- styling --------------------------------------------------------------------
    def _style(self):
        T, ui = THEME, self.fonts["ui"]
        st = ttk.Style(self)
        try:
            st.theme_use("clam")
        except tk.TclError:
            pass
        st.configure(".", background=T["bg1"], foreground=T["text"], fieldbackground=T["panel2"], bordercolor=T["border"],
                     lightcolor=T["border"], darkcolor=T["border"], troughcolor=T["bg2"], focuscolor=T["bg1"], font=(ui, 10))
        st.configure("TFrame", background=T["bg1"])
        st.configure("TLabel", background=T["bg1"], foreground=T["text"], font=(ui, 10))
        st.configure("Header.TLabel", font=(ui, 25, "bold"), foreground=T["text"])
        st.configure("Sub.TLabel", font=(ui, 9), foreground=T["cyan"])
        st.configure("TButton", padding=(12, 6), background=T["panel2"], foreground=T["text"], bordercolor=T["border_hi"], font=(ui, 10))
        st.map("TButton", background=[("active", "#1c3b5a"), ("disabled", T["bg2"])], foreground=[("disabled", T["faint"])])
        st.configure("Accent.TButton", background="#0b7a99", foreground="#ffffff", bordercolor="#14b8d4", font=(ui, 10, "bold"))
        st.map("Accent.TButton", background=[("active", "#0e97bb"), ("disabled", T["bg2"])], foreground=[("disabled", T["faint"])])
        st.configure("TNotebook", background=T["bg0"], borderwidth=0, tabmargins=(0, 0, 0, 0))
        st.configure("TNotebook.Tab", padding=(18, 8), background=T["bg2"], foreground=T["dim"], font=(ui, 10), borderwidth=0)
        st.map("TNotebook.Tab", background=[("selected", T["panel2"])], foreground=[("selected", T["cyan"])])
        st.configure("TCombobox", fieldbackground=T["panel2"], background=T["panel2"], foreground=T["text"], arrowcolor=T["cyan"],
                     bordercolor=T["border_hi"], selectbackground=T["panel2"], selectforeground=T["text"])
        st.map("TCombobox", fieldbackground=[("readonly", T["panel2"])], foreground=[("readonly", T["text"])])
        st.configure("TEntry", fieldbackground=T["panel2"], foreground=T["text"], insertcolor=T["text"], bordercolor=T["border_hi"])
        st.configure("TRadiobutton", background=T["bg1"], foreground=T["text"], font=(ui, 10), indicatorcolor=T["panel2"])
        st.map("TRadiobutton", indicatorcolor=[("selected", T["cyan"])], background=[("active", T["bg1"])])
        st.configure("Horizontal.TScale", background=T["bg1"], troughcolor=T["bg2"])
        st.configure("Vertical.TScrollbar", background=T["panel2"], troughcolor=T["bg1"], arrowcolor=T["dim"], bordercolor=T["bg1"])
        st.configure("Treeview", background=T["panel"], fieldbackground=T["panel"], foreground=T["text"], rowheight=24,
                     bordercolor=T["border"], font=(ui, 9))
        st.configure("Treeview.Heading", background=T["panel2"], foreground=T["dim"], font=(ui, 9, "bold"), bordercolor=T["border"])
        st.map("Treeview", background=[("selected", "#1c3b5a")])
        self.option_add("*TCombobox*Listbox.background", T["panel2"])
        self.option_add("*TCombobox*Listbox.foreground", T["text"])
        self.option_add("*TCombobox*Listbox.selectBackground", "#1c3b5a")
        self.option_add("*TCombobox*Listbox.font", (ui, 10))

    # ---- small widget helpers ------------------------------------------------------------
    def _lbl(self, parent, text="", fg=None, size=10, bold=False, bg=None, **kw):
        return tk.Label(parent, text=text, bg=bg or parent.cget("bg"), fg=fg or THEME["text"],
                        font=(self.fonts["ui"], size, "bold") if bold else (self.fonts["ui"], size), **kw)

    def _set_label(self, label, text, fg=None):
        key = (text, fg)
        if self._label_cache.get(label) != key:
            label.configure(text=text) if fg is None else label.configure(text=text, fg=fg)
            self._label_cache[label] = key

    def _chip(self, parent):
        return tk.Label(parent, text="", bg=THEME["panel"], fg=THEME["dim"], font=(self.fonts["ui"], 9, "bold"), padx=10, pady=4)

    def _section(self, parent, title):
        f = tk.Frame(parent, bg=THEME["bg1"])
        f.pack(fill="x", pady=(0, 6))
        tk.Label(f, text=title, bg=THEME["bg1"], fg=THEME["cyan"], font=(self.fonts["ui"], 10, "bold"), anchor="w").pack(fill="x", padx=4, pady=(8, 2))
        tk.Frame(f, bg=THEME["border"], height=1).pack(fill="x", padx=4, pady=(0, 4))
        return f

    def _card(self, parent, row, col, title, vsize=17):
        box = tk.Frame(parent, bg=THEME["panel"], highlightbackground=THEME["border"], highlightthickness=1)
        box.grid(row=row, column=col, sticky="nsew", padx=4, pady=4)
        tk.Label(box, text=title, bg=THEME["panel"], fg=THEME["dim"], font=(self.fonts["ui"], 9), anchor="w").pack(fill="x", padx=10, pady=(7, 0))
        v = tk.Label(box, text="-", bg=THEME["panel"], fg=THEME["text"], font=(self.fonts["ui"], vsize, "bold"), anchor="w")
        v.pack(fill="x", padx=10)
        s = tk.Label(box, text="", bg=THEME["panel"], fg=THEME["faint"], font=(self.fonts["ui"], 8), anchor="w", justify="left", wraplength=150)
        s.pack(fill="x", padx=10, pady=(0, 7))
        return v, s

    # ---- layout ------------------------------------------------------------------------
    def build_ui(self):
        self.columnconfigure(0, weight=1)
        self.rowconfigure(2, weight=1)
        self._build_header()
        self.banner = tk.Label(self, text=DISCLAIMER, bg="#3a2205", fg="#fde68a", font=(self.fonts["ui"], 9), anchor="w",
                               justify="left", padx=14, pady=5)
        self.banner.grid(row=1, column=0, sticky="ew")
        self.banner.bind("<Configure>", lambda e: self.banner.configure(wraplength=max(200, e.width - 28)))
        body = tk.Frame(self, bg=THEME["bg0"])
        body.grid(row=2, column=0, sticky="nsew", padx=14, pady=(10, 6))
        body.columnconfigure(0, weight=1)
        body.columnconfigure(1, weight=0)
        body.rowconfigure(0, weight=1)
        self.nb = ttk.Notebook(body)
        self.nb.grid(row=0, column=0, sticky="nsew", padx=(0, 12))
        self.side = ScrollFrame(body, THEME["bg1"])
        self.side.canvas.configure(width=372)
        self.side.grid(row=0, column=1, sticky="nsew")
        self._build_intersection_tab()
        self._build_compare_tab()
        self._build_experiments_tab()
        self._build_decisions_tab()
        self._build_figures_tab()
        self._build_classic_tab()
        self._build_side()
        self._build_diag()
        self._update_buttons()

    def _build_header(self):
        hdr = tk.Frame(self, bg=THEME["bg1"], highlightbackground=THEME["border"], highlightthickness=0)
        hdr.grid(row=0, column=0, sticky="ew")
        hdr.columnconfigure(1, weight=1)
        left = tk.Frame(hdr, bg=THEME["bg1"])
        left.grid(row=0, column=0, sticky="w", padx=18, pady=(10, 8))
        tk.Label(left, text="Pachpedi Naka", bg=THEME["bg1"], fg=THEME["text"], font=(self.fonts["ui"], 20, "bold")).pack(anchor="w")
        tk.Label(left, text="Smart traffic optimization  |  signal control command center", bg=THEME["bg1"], fg=THEME["cyan"],
                 font=(self.fonts["ui"], 9)).pack(anchor="w")
        chips = tk.Frame(hdr, bg=THEME["bg1"])
        chips.grid(row=0, column=1, sticky="w", padx=10)
        self.chip_engine, self.chip_ctl, self.chip_state = self._chip(chips), self._chip(chips), self._chip(chips)
        for c in (self.chip_engine, self.chip_ctl, self.chip_state):
            c.pack(side="left", padx=4)
        right = tk.Frame(hdr, bg=THEME["bg1"])
        right.grid(row=0, column=2, sticky="e", padx=18)
        self.btn_start = ttk.Button(right, text="Start", style="Accent.TButton", command=self.cmd_start)
        self.btn_pause = ttk.Button(right, text="Pause", command=self.cmd_pause)
        self.btn_resume = ttk.Button(right, text="Resume", style="Accent.TButton", command=self.cmd_resume)
        self.btn_reset = ttk.Button(right, text="Reset", command=self.cmd_reset)
        for b in (self.btn_start, self.btn_pause, self.btn_resume, self.btn_reset):
            b.pack(side="left", padx=4)
        tk.Label(right, text="Speed", bg=THEME["bg1"], fg=THEME["dim"], font=(self.fonts["ui"], 9)).pack(side="left", padx=(14, 4))
        sp = ttk.Combobox(right, textvariable=self.v_speed, state="readonly", width=6,
                          values=[f"{s:g}x" for s in PlaybackClock.SPEEDS])
        sp.pack(side="left")
        sp.bind("<<ComboboxSelected>>", self._on_speed)
        tk.Frame(self, bg=THEME["border"], height=1).place(x=0, y=0, relwidth=1, height=0)

