        self.view_host.grid(row=0, column=0, sticky="nsew", pady=(8, 6))
        self.view_host.rowconfigure(0, weight=1)
        self.engine_msg = tk.Label(self.view_host, text="Loading engine...", bg=THEME["bg0"], fg=THEME["dim"],
                                   font=(self.fonts["ui"], 12), justify="center", wraplength=620)
        self.engine_msg.grid(row=0, column=0, sticky="nsew")
        self.view_host.columnconfigure(0, weight=1)
        self.strip = TimelineStrip(tab, self.fonts, height=120)
        self.strip.grid(row=1, column=0, sticky="ew")
        bar = tk.Frame(tab, bg=THEME["bg1"])
