        self.lbl_time.grid(row=0, column=0, padx=(10, 6), pady=8)
        self.scale = ttk.Scale(bar, from_=0, to=1, orient="horizontal", command=self._on_scrub)
        self.scale.grid(row=0, column=1, sticky="ew", padx=6)
