        self.scale.bind("<ButtonRelease-1>", lambda e: setattr(self, "_dragging", False))
        tk.Label(bar, text="Timeline window", bg=THEME["bg1"], fg=THEME["dim"], font=(self.fonts["ui"], 9)).grid(row=0, column=2, padx=(10, 4))
        win = ttk.Combobox(bar, textvariable=self.v_window, state="readonly", width=9, values=list(TimelineStrip.MODES))
