    # ---- tab: controller decisions -----------------------------------------------------------------------------
    def _build_decisions_tab(self):
        tab = tk.Frame(self.nb, bg=THEME["bg1"])
        self.nb.add(tab, text="Controller decisions")
        tab.columnconfigure(0, weight=1)
        tab.rowconfigure(2, weight=1)
        tk.Label(tab, text="Why the controller acted", bg=THEME["bg1"], fg=THEME["text"], font=(self.fonts["ui"], 13, "bold"), anchor="w").grid(row=0, column=0, sticky="w", padx=10, pady=(10, 0))
        self.dec_info = tk.Label(tab, text="", bg=THEME["bg1"], fg=THEME["dim"], font=(self.fonts["ui"], 9), anchor="w", justify="left", wraplength=900)
        self.dec_info.grid(row=1, column=0, sticky="ew", padx=10, pady=(0, 6))
        cols = ("time", "event", "phase", "reason", "scores")
        self.dec_tree = ttk.Treeview(tab, columns=cols, show="headings")
        for c, h, w, st in (("time", "Time", 70, False), ("event", "Event", 110, False), ("phase", "Phase", 80, False), ("reason", "Reason", 430, True), ("scores", "Phase scores at decision", 330, True)):
            self.dec_tree.heading(c, text=h)
            self.dec_tree.column(c, width=w, anchor="w", stretch=st)
        vs = ttk.Scrollbar(tab, orient="vertical", command=self.dec_tree.yview)
        self.dec_tree.configure(yscrollcommand=vs.set)
        self.dec_tree.grid(row=2, column=0, sticky="nsew", padx=(10, 0), pady=(0, 10))
        vs.grid(row=2, column=1, sticky="ns", pady=(0, 10), padx=(0, 10))
        self._dec_times, self._dec_ids, self._dec_last = [], [], -1

    def _fill_decisions(self):
        self.dec_tree.delete(*self.dec_tree.get_children())
        self._dec_times, self._dec_ids, self._dec_last = [], [], -1
        b = self._focus_bundle()
        if not b:
            return
        if not b.decisions:
            self.dec_info.configure(text=f"{CONTROLLER_LABELS[b.controller]} follows timing rules and keeps no decision log. Choose "
                                         "'Adaptive pressure (final)' or 'Competitor-style' to see why each switch happened.")
            return
        hold = sum(1 for d in b.decisions if d["event"] == "HOLD_GREEN")
        self.dec_info.configure(text=f"{CONTROLLER_LABELS[b.controller]}: {len(b.decisions)} logged decisions in this run ({hold} idle holds). Every row is written by the "
                                     "controller itself while the engine runs; the highlighted row follows the replay time.")
        for d in b.decisions:
            scores = d.get("scores")
            txt = "  ".join(f"{k.replace('PH_APP_', '')}={v}" for k, v in scores.items()) if scores else (f"next {d['next']}" if d.get("next") else "")
            iid = self.dec_tree.insert("", "end", values=(fmt_clock(d["t"]), d["event"], d["phase"].replace("PH_APP_", ""), d["reason"], txt))
            self._dec_times.append(d["t"])
            self._dec_ids.append(iid)

    def _update_decision(self, t):
        b = self._focus_bundle()
        if not b or not b.decisions:
            self._set_label(self.m_decision[0], "no log")
            self._set_label(self.m_decision[1], "rule-based timing")
            return
        i = bisect.bisect_right(self._dec_times, t) - 1
        if i < 0:
            self._set_label(self.m_decision[0], "none yet")
            self._set_label(self.m_decision[1], "")
            return
        d = b.decisions[i]
        self._set_label(self.m_decision[0], f"{d['event'].replace('_', ' ').title()}")
        self._set_label(self.m_decision[1], f"{fmt_clock(d['t'])}  {d['phase'].replace('PH_APP_', '')}\n{d['reason']}")
        if i != self._dec_last and self._dec_ids:
            self._dec_last = i
            try:
                self.dec_tree.selection_set(self._dec_ids[i])
                self.dec_tree.see(self._dec_ids[i])
            except tk.TclError:
                pass

